def drop_armed_measurement(steps):
    fill = next(i for i, step in enumerate(steps)
                if step[0] == "fill" and len(str(step[2])) == 40)
    steps[:] = [step for i, step in enumerate(steps)
                if not (i > fill and step[0] == "composerControls")]
